import{_ as a,o,c as e,a0 as r}from"./chunks/framework.Caz7a20Z.js";const c=JSON.parse('{"title":"除讨论外全过了一遍，离投稿又近一步","description":"今天把除了讨论以外的部分全部重新过了一遍、都改了；讨论还存在问题留给明天，明天再改补充文件并整体过一遍，感觉就能准备投稿了。","frontmatter":{"title":"除讨论外全过了一遍，离投稿又近一步","date":"2026-08-28T00:00:00.000Z","tags":["日记"],"description":"今天把除了讨论以外的部分全部重新过了一遍、都改了；讨论还存在问题留给明天，明天再改补充文件并整体过一遍，感觉就能准备投稿了。"},"headers":[],"relativePath":"posts/diary-20260828.md","filePath":"posts/diary-20260828.md","lastUpdated":null}'),s={name:"posts/diary-20260828.md"};function i(n,t,l,d,p,u){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="除讨论外全过了一遍-离投稿又近一步" tabindex="-1">除讨论外全过了一遍，离投稿又近一步 <a class="header-anchor" href="#除讨论外全过了一遍-离投稿又近一步" aria-label="Permalink to &quot;除讨论外全过了一遍，离投稿又近一步&quot;">​</a></h1><p>今天是&quot;通读改稿&quot;的一天，进展挺实在的 ✍️。</p><h2 id="正文-除了讨论-全过了一遍" tabindex="-1">正文：除了讨论，全过了一遍 <a class="header-anchor" href="#正文-除了讨论-全过了一遍" aria-label="Permalink to &quot;正文：除了讨论，全过了一遍&quot;">​</a></h2><p>把论文从头捋了一遍，<strong>除了讨论（Discussion）之外的内容全部过了一遍，而且都重新改动了一遍</strong>。前言、方法、结果这些部分，之前是&quot;大致能用&quot;，今天是一节节抠过、改过，读起来顺了不少。</p><p>&quot;全部过一遍&quot;听着轻巧，实际是把之前欠的细致活儿都补上了——语句、逻辑衔接、前后一致性，这些不吃时间的细节，最磨人但最提质感。</p><h2 id="讨论-还有问题-留给明天" tabindex="-1">讨论：还有问题，留给明天 <a class="header-anchor" href="#讨论-还有问题-留给明天" aria-label="Permalink to &quot;讨论：还有问题，留给明天&quot;">​</a></h2><p><strong>讨论部分还存在问题</strong>，今天没啃下来。讨论是最难写、也最见功力的地方，要把它和结果、和已有研究摆在一起说清楚，确实得单独留时间琢磨。留给明天专门收拾它。</p><h2 id="明天-讨论-补充材料-再过一遍" tabindex="-1">明天：讨论 + 补充材料 + 再过一遍 <a class="header-anchor" href="#明天-讨论-补充材料-再过一遍" aria-label="Permalink to &quot;明天：讨论 + 补充材料 + 再过一遍&quot;">​</a></h2><p>明天的活儿排得挺满：</p><ol><li><strong>改讨论</strong>——把还没理顺的地方啃下来；</li><li><strong>改补充文件（Supplementary Materials）</strong>——补材料也得修一修；</li><li><strong>然后再全部过一遍</strong>——从头到尾再顺一遍。</li></ol><p>这套走完，<strong>感觉就可以准备投稿了</strong> 😮。</p><h2 id="就这样吧" tabindex="-1">就这样吧 <a class="header-anchor" href="#就这样吧" aria-label="Permalink to &quot;就这样吧&quot;">​</a></h2><p>从代码整理、到结果、到作图、到一节节改稿，这么长的战线，终于能看到&quot;投稿&quot;这两个字的轮廓了。当然，&quot;感觉可以准备&quot;和&quot;真的投出去&quot;之间还有距离，但至少方向明确了。</p><p>能看到终点线的感觉真好，嘿嘿。明天能做成什么样，就看明天了，加油 💪！</p>',14)])])}const q=a(s,[["render",i]]);export{c as __pageData,q as default};
